 test("abnormal middle RPM response cannot certify four stages",[&]{auto e=make();auto s=sample();for(int i=0;i<3;++i)EngineTestAccess::tick(*e,s,now+i*2000);Command c;c.kind=8;c.admin=true;e->submit(c);EngineTestAccess::tick(*e,s,now+6000);int stages[]{7,4,2,1},rpm[]{4000,6000,6000,2500};for(int i=0;i<4;++i){s.level={stages[i],stages[i]};s.rpm={rpm[i],rpm[i]};for(int j=1;j<=4;++j)EngineTestAccess::tick(*e,s,now+6000+i*8000+j*2000);}return e->snapshot().commissionStatus==-1&&e->snapshot().requested==128;});
