 test("wake waits for late vendor source before restoring Smart",[&]{auto e=make();auto s=sample();EngineTestAccess::setMode(*e,Mode::Smart);EngineTestAccess::power(*e,3);EngineTestAccess::power(*e,4);VendorSample missing;for(int i=0;i<4;++i)EngineTestAccess::tickVendor(*e,s,missing,now+i*2000);if(e->snapshot().mode!=0||!e->snapshot().resumePending)return false;EngineTestAccess::tick(*e,s,now+8000);return e->snapshot().mode==2&&!e->snapshot().resumePending;});
